import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Input-and-Output-Formats.md","filePath":"manual-zh/Input-and-Output-Formats.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Input-and-Output-Formats.md"};function n(p,t,m,c,s,_){return e(),a("div",null,[...t[0]||(t[0]=[r('<h4 id="_6-7-4-输入与输出格式" tabindex="-1">6.7.4 输入与输出格式 <a class="header-anchor" href="#_6-7-4-输入与输出格式" aria-label="Permalink to &quot;6.7.4 输入与输出格式&quot;">​</a></h4><p><em>输入格式</em> 描述如何将输入字段的内容解释为数字或字符串。它可以指定字段包含普通十进制数字、时间或日期、二进制或十六进制表示的数字，或其他几种表示法之一。输入格式由 <code>DATA LIST</code> 等将数据或语法文件读入 PSPP 活动数据集的命令使用。</p><p>每个输入格式都对应一个默认的 <em>输出格式</em>，指定稍后输出该值时使用的格式。始终可以显式指定类似于输入格式的输出格式。通常这是默认设置，但在输入格式不利于人类阅读的情况下，例如二进制或十六进制格式，默认输出格式是更易于阅读的十进制格式。</p><p>每个变量有两个输出格式，称为其 <em>打印格式</em> 和 <em>写入格式</em>。打印格式用于大多数输出上下文；写入格式仅由 <code>WRITE</code> 使用（见 <a href="./WRITE">WRITE</a>）。新创建的变量具有相同的打印格式和写入格式，而最常用的更改格式命令 <code>FORMATS</code>（见 <a href="./FORMATS">FORMATS</a>）也会将两者都设置为相同的值。因此，大多数情况下，打印格式和写入格式之间的区别并不重要。</p><p>输入和输出格式以 <code>TYPEw</code> 或 <code>TYPEw.d</code> 形式的 <em>格式规范</em> 提供给 PSPP，其中 TYPE 是后面描述的格式类型之一，w 是以列为单位的字段宽度，d 是可选的小数位数。如果省略 d，则假定为 0。某些格式不允许指定非零的 d。</p><p>以下各节描述 PSPP 支持的输入和输出格式。</p><table tabindex="0"><thead><tr><th>• 基本数字格式</th><th></th><th></th></tr></thead><tbody><tr><td>• 自定义货币格式</td><td></td><td></td></tr><tr><td>• 传统数字格式</td><td></td><td></td></tr><tr><td>• 二进制与十六进制数字格式</td><td></td><td></td></tr><tr><td>• 时间与日期格式</td><td></td><td></td></tr><tr><td>• 日期组成部分格式</td><td></td><td></td></tr><tr><td>• 字符串格式</td><td></td><td></td></tr></tbody></table>',7)])])}const l=d(o,[["render",n]]);export{h as __pageData,l as default};
